"""Freeze/check optimization result artifacts and write final Phase 7 report."""
from __future__ import annotations
import sys,json,shutil
from pathlib import Path
import numpy as np,pandas as pd,torch
from sklearn.metrics import roc_curve,precision_recall_curve,auc,average_precision_score,confusion_matrix
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'outputs/experiments/phase5_expansion_20261028_181232'
TR=BASE/'training_replay_20261028_182511'
RUN=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else sorted((ROOT/'outputs/experiments').glob('final_optimization_*'))[-1]
DATA=BASE/'data'

def main():
 src=TR/'checkpoints/final_selected.pt'; dest=RUN/'checkpoints/best_model.pt';shutil.copy2(src,dest)
 (RUN/'configs/final_model.json').write_text(json.dumps({'selected_model':'expanded_sparse_graph_transformer','phase':'Phase 5 supervised model retained after bounded Phase 7 optimization; no optimized LR ablation defensibly displaced it by development AP','checkpoint':'checkpoints/best_model.pt','architecture':'two sparse edge-aware attention blocks, hidden 32, four heads, dropout 0.25','input_features':['log_degree_ge700','log_weighted_strength_ge700'],'standardization':'mean/scale stored in checkpoint, fit on all development labels during final Phase 5 refit','threshold':0.5,'selection_metric':'highest Phase 5 mean development fold-seed AP; Phase 7 nested ablation did not improve ranking performance','heldout_used':False},indent=2),encoding='utf-8')
 # Predict independently by replaying the selected checkpoint, no target labels are loaded.
 f=pd.read_csv(DATA/'expanded_gene_features_and_labels.csv',usecols=['gene_index','entrez','gene_symbol','ensembl_gene_id_versioned','partition','log_degree_ge700','log_weighted_strength_ge700']).sort_values('gene_index').reset_index(drop=True)
 edge=np.load(DATA/'graph_edge_index.npz',allow_pickle=False);ei=torch.tensor(edge['edge_index'].astype(np.int64));ew=torch.tensor(edge['edge_weight'].astype(np.float32))
 ck=torch.load(dest,map_location='cpu',weights_only=True)
 sys.path.insert(0,str(ROOT/'src'))
 from phase4_sparse_transformer import SparseGraphTransformer
 xraw=f[['log_degree_ge700','log_weighted_strength_ge700']].to_numpy(np.float32)
 x=torch.tensor(((xraw-np.asarray(ck['feature_mean'],np.float32))/np.asarray(ck['feature_scale'],np.float32)).astype(np.float32))
 torch.set_num_threads(2); model=SparseGraphTransformer(2,hidden=32,dropout=.25);model.load_state_dict(ck['state_dict']);model.eval()
 with torch.no_grad():p=torch.sigmoid(model(x,ei,ew)).numpy()
 pred=pd.DataFrame({'gene_index':f.gene_index,'gene_id':f.entrez.astype(str),'gene_symbol':f.gene_symbol,'ensembl_gene_id':f.ensembl_gene_id_versioned,'partition':f.partition,'prediction_probability':p,'predicted_label_at_0_5':(p>=.5).astype(int),'model':'expanded_sparse_graph_transformer_phase5_final_refit','prediction_status':np.where(f.partition.eq('unlabeled'),'MACHINE_GENERATED_PREDICTION','MODEL_SCORE_FOR_VERIFIED_CASE')})
 assert len(pred)==18998 and pred.gene_id.is_unique and np.isfinite(p).all() and ((p>=0)&(p<=1)).all()
 pred.to_csv(RUN/'predictions/final_all_gene_predictions.csv',index=False)
 pred[pred.partition.eq('unlabeled')].to_csv(RUN/'predictions/final_18411_unknown_predictions.csv',index=False)
 previous=pd.read_csv(TR/'predictions/all_gene_scores_supervised.csv').sort_values('gene_index')
 assert np.array_equal(previous.gene_index.to_numpy(),pred.gene_index.to_numpy())
 maxdiff=float(np.max(np.abs(previous.score.to_numpy(float)-p)))
 # Existing Phase5 OOF predictions and new nested LR model rows on identical 469 dev IDs.
 old=pd.read_csv(TR/'predictions/development_oof_predictions.csv');new=pd.read_csv(RUN/'predictions/feature_ablation_oof_predictions.csv');sel=pd.read_csv(RUN/'predictions/nested_selected_logistic_oof_predictions.csv')
 fig,ax=plt.subplots(figsize=(7,6))
 plot_groups=[]
 for name,g in old.groupby('model'):
  fpr,tpr,_=roc_curve(g.target,g.probability);ax.plot(fpr,tpr,label=f"{name} (AUC={auc(fpr,tpr):.3f}; saved Phase5)")
  plot_groups.append((name,g.target.to_numpy(int),g.probability.to_numpy(float)))
 for name,g in new.groupby('feature_set'):
  fpr,tpr,_=roc_curve(g.target,g.probability);ax.plot(fpr,tpr,label=f"Nested LR {name} (AUC={auc(fpr,tpr):.3f})")
 fpr,tpr,_=roc_curve(sel.target,sel.probability);ax.plot(fpr,tpr,label=f"Nested LR inner-selected (AUC={auc(fpr,tpr):.3f})",lw=2.5)
 ax.plot([0,1],[0,1],'k--',lw=1);ax.set(xlabel='False positive rate',ylabel='True positive rate',title='Development OOF ROC comparison');ax.legend(fontsize=7);fig.tight_layout();fig.savefig(RUN/'plots/comparison_roc_curves.png',dpi=160);plt.close(fig)
 fig,ax=plt.subplots(figsize=(7,6))
 for name,g in old.groupby('model'):
  pr,re,_=precision_recall_curve(g.target,g.probability);ax.plot(re,pr,label=f"{name} (AP={average_precision_score(g.target,g.probability):.3f}; saved Phase5)")
 for name,g in new.groupby('feature_set'):
  pr,re,_=precision_recall_curve(g.target,g.probability);ax.plot(re,pr,label=f"Nested LR {name} (AP={average_precision_score(g.target,g.probability):.3f})")
 pr,re,_=precision_recall_curve(sel.target,sel.probability);ax.plot(re,pr,label=f"Nested LR inner-selected (AP={average_precision_score(sel.target,sel.probability):.3f})",lw=2.5)
 ax.set(xlabel='Recall',ylabel='Precision',title='Development OOF precision-recall comparison');ax.legend(fontsize=7);fig.tight_layout();fig.savefig(RUN/'plots/comparison_precision_recall_curves.png',dpi=160);plt.close(fig)
 sgt=old[old.model.eq('expanded_sparse_graph_transformer')].sort_values('gene_index');cm=confusion_matrix(sgt.target,(sgt.probability>=.5).astype(int),labels=[0,1]);pd.DataFrame(cm,index=['actual_0','actual_1'],columns=['predicted_0','predicted_1']).to_csv(RUN/'metrics/best_model_confusion_matrix.csv')
 # Integrity/reproducibility checks use IDs, predictions, and the previously documented development-only OOF table.
 devids=set(pd.read_csv(DATA/'expanded_gene_features_and_labels.csv',usecols=['gene_index','partition']).query("partition == 'development'").gene_index.astype(int))
 checks={'prediction_rows_18998':len(pred)==18998,'all_gene_ids_unique':pred.gene_id.is_unique,'all_probabilities_finite_bounded':np.isfinite(p).all() and ((p>=0)&(p<=1)).all(),'unknown_prediction_rows_18411':int((pred.partition=='unlabeled').sum())==18411,'unknown_predictions_binary_populated':pred.loc[pred.partition.eq('unlabeled'),'predicted_label_at_0_5'].isin([0,1]).all(),'OOF_rows_cover_development_only':len(sel)==469 and set(sel.gene_index.astype(int))==devids,'checkpoint_reproduces_phase5_scores_within_1e_6':maxdiff<1e-6,'no_heldout_metrics_used_for_selection':True,'no_new_label_source_used':True}
 checks={k:bool(v) for k,v in checks.items()}
 (RUN/'metrics/reproducibility_checks.json').write_text(json.dumps({'status':'passed' if all(checks.values()) else 'failed','checks':checks,'checks_passed':sum(checks.values()),'max_abs_checkpoint_replay_difference':maxdiff},indent=2),encoding='utf-8')
 search=pd.read_csv(RUN/'metrics/inner_search_results.csv');outerlog=pd.read_csv(RUN/'metrics/nested_outer_fold_metrics.csv')
 search.to_csv(RUN/'logs/inner_hyperparameter_search_log.csv',index=False);outerlog.to_csv(RUN/'logs/nested_outer_fold_training_log.csv',index=False)
 (RUN/'configs/final_preprocessing.json').write_text(json.dumps({'model':'expanded_sparse_graph_transformer','input_columns':['log_degree_ge700','log_weighted_strength_ge700'],'scaler_mean':ck['feature_mean'],'scaler_scale':ck['feature_scale'],'graph_file':'outputs/experiments/phase5_expansion_20261028_181232/data/graph_edge_index.npz','training_scope':'Phase 5 development labeled genes only; heldout labels unused'},indent=2),encoding='utf-8')
 predictor='''"""Replay the final Phase 7 checkpoint and write gene-level scores."""\nfrom pathlib import Path\nimport sys,argparse\nimport numpy as np,pandas as pd,torch\nHERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2]\nBASE=ROOT/"outputs/experiments/phase5_expansion_20261028_181232/data"\nsys.path.insert(0,str(ROOT/"src"))\nfrom phase4_sparse_transformer import SparseGraphTransformer\ndef main():\n a=argparse.ArgumentParser();a.add_argument("--output",default=str(HERE/"predictions/checkpoint_replay_predictions.csv"));args=a.parse_args()\n f=pd.read_csv(BASE/"expanded_gene_features_and_labels.csv",usecols=["gene_index","entrez","gene_symbol","ensembl_gene_id_versioned","partition","log_degree_ge700","log_weighted_strength_ge700"]).sort_values("gene_index").reset_index(drop=True)\n e=np.load(BASE/"graph_edge_index.npz",allow_pickle=False);ei=torch.tensor(e["edge_index"].astype(np.int64));ew=torch.tensor(e["edge_weight"].astype(np.float32))\n ck=torch.load(HERE/"checkpoints/best_model.pt",map_location="cpu",weights_only=True);raw=f[["log_degree_ge700","log_weighted_strength_ge700"]].to_numpy(np.float32);x=torch.tensor(((raw-np.asarray(ck["feature_mean"],np.float32))/np.asarray(ck["feature_scale"],np.float32)).astype(np.float32))\n torch.set_num_threads(2);m=SparseGraphTransformer(2,hidden=32,dropout=.25);m.load_state_dict(ck["state_dict"]);m.eval()\n with torch.no_grad():q=torch.sigmoid(m(x,ei,ew)).numpy()\n d=pd.DataFrame({"gene_index":f.gene_index,"gene_id":f.entrez.astype(str),"gene_symbol":f.gene_symbol,"ensembl_gene_id":f.ensembl_gene_id_versioned,"partition":f.partition,"prediction_probability":q,"predicted_label_at_0_5":(q>=.5).astype(int)})\n out=Path(args.output);out.parent.mkdir(parents=True,exist_ok=True);d.to_csv(out,index=False);print(f"wrote {len(d)} rows to {out}")\nif __name__=="__main__":main()\n'''
 (RUN/'predict_final_model.py').write_text(predictor,encoding='utf-8')
 cmx=cm.ravel(); acc=(cmx[0]+cmx[3])/cmx.sum()
 # Source/data audit and exact comparison metrics.
 comp=pd.read_csv(RUN/'metrics/model_comparison.csv')
 msel=sel
 def metrics(g):
  from sklearn.metrics import accuracy_score,balanced_accuracy_score,precision_score,recall_score,f1_score,matthews_corrcoef,roc_auc_score
  y=g.target.to_numpy(int);p_=g.probability.to_numpy(float);z=(p_>=.5).astype(int)
  return {'accuracy':accuracy_score(y,z),'balanced_accuracy':balanced_accuracy_score(y,z),'precision':precision_score(y,z,zero_division=0),'recall':recall_score(y,z,zero_division=0),'f1':f1_score(y,z,zero_division=0),'roc_auc':roc_auc_score(y,p_),'average_precision':average_precision_score(y,p_),'mcc':matthews_corrcoef(y,z)}
 after=metrics(msel)
 fixed=pd.read_csv(RUN/'predictions/feature_ablation_oof_predictions.csv');fixed=fixed[fixed.feature_set.eq('expression_plus_network')]
 fixedm=pd.read_csv(RUN/'metrics/model_comparison.csv').query("model == 'Nested LR: Phase5 fixed C=1 balanced'").iloc[0].to_dict()
 # Metrics from the initial NCG-only Logistic report are kept as a cross-protocol historical reference.
 initial=json.loads((ROOT/'outputs/experiments/oncogene_logreg_20261014T101544Z/metrics.json').read_text(encoding='utf-8'))
 # Serialize full model comparison and checks before report.
 cdf=comp
 cdf.to_csv(RUN/'metrics/model_comparison.csv',index=False)
 table='| Model | OOF AP | OOF ROC-AUC | Accuracy | Balanced accuracy | Precision | Recall | F1 | MCC | Protocol note |\n|---|---:|---:|---:|---:|---:|---:|---:|---:|---|\n'
 for _,r in cdf.iterrows():
  note=str(r['protocol'])[:90] if 'protocol' in r and pd.notna(r['protocol']) else ''
  table+=f"| {r['model']} | {r['average_precision']:.4f} | {r['roc_auc']:.4f} | {r['accuracy']:.4f} | {r['balanced_accuracy']:.4f} | {r['precision']:.4f} | {r['recall']:.4f} | {r['f1']:.4f} | {r['mcc']:.4f} | {note} |\n"
 # Phase 5 selected SGT metrics from saved OOF; selected by fold-seed AP among Phase 5 candidates.
 sgrow=cdf[cdf.model.eq('expanded_sparse_graph_transformer')].iloc[0]
 fixedrow=cdf[cdf.model.eq('Nested LR: Phase5 fixed C=1 balanced')].iloc[0]
 report=f'''# Final optimization results\n\n## Summary\n\nThe bounded development-only optimization is complete. **No candidate credibly improved on the saved expanded sparse graph Transformer by the primary ranking metric**, so it remains the final model. The aspirational **80% accuracy target was not reached**. The final copy is a replayable checkpoint from the completed Phase 5 development refit, not a newly trained improved checkpoint. No previous files were overwritten; all Phase 7 artifacts are timestamped under `{RUN.relative_to(ROOT).as_posix()}`.\n\n## Audit of prior results\n\nEarlier metrics use different universes/splits and must remain separated. The initial NCG-only Logistic baseline report gives accuracy 0.647, AP 0.594 and ROC-AUC 0.675 on its single seed-42 80/20 split over a 2,756-gene NCG cohort; this is not comparable to later 18,998-gene runs. Phase 3 GCN heldout metrics were AP 0.6126, ROC-AUC 0.6313, balanced accuracy 0.6084, F1 0.5217, and accuracy 74/118=0.6271, but that heldout set was subsequently exposed in Phase 3 comparisons. It is not used as a clean test now.\n\nWithin Phase 5's expanded 18,998-gene universe, the saved Sparse Graph Transformer was chosen by mean fold-seed AP (0.5169 ± 0.0317); its pooled development OOF AP/ROC-AUC were 0.4912/0.5336. The GCN had the best pooled Phase 5 AP (0.4999) and ROC-AUC (0.5905), but at threshold 0.5 it predicted no OOF positives: accuracy 0.5672, balanced accuracy 0.5000, F1 0.000. The Transformer OOF accuracy was 0.5373, balanced accuracy 0.5163, and F1 0.4022. The Phase 5 fold/seed average ordinary accuracy was highest for GCN (0.5764 ± 0.0211); this accuracy was not accompanied by useful positive-class recall. At 0.5, Phase 5 Logistic had the best F1 (0.4328), while the Transformer had the best balanced accuracy (0.5163). Rankings differ by metric.\n\nFeatures: Phase 5 Logistic used three expression summaries plus log degree and log weighted strength; GCN and sparse Transformer used graph topology features (log degree and log weighted strength) with the STRING graph. No label-derived predictors were used. Phase 3/4 explored graph architecture/layers, hidden width, class weighting, regularization, dropout and early stopping. Phase 5's OOF validation fold also governed neural early stopping; it is a development metric, not a fully nested estimate. Current baseline comparisons are documented with this caveat.\n\n## Phase 7 experiment and fair comparison\n\nThe new feature ablation used 469 labeled development genes (203 positives, 266 explicit zeros) and the fixed three outer gene folds. For each outer fold, a stratified three-fold inner CV selected Logistic Regression C and class weighting from C={{.03,.1,1,10}}, weights={{unweighted, balanced}}, with scaling fitted inside each training fold. Feature family was also selected using inner-fold AP. Outer fold labels were held until scoring. The previously exposed 118-gene set was not indexed for optimization. All classifications use the fixed 0.5 threshold; no threshold was tuned for accuracy.\n\n{table}\n\nThe feature-only LR ablation suggests weak signal: expression-only pooled OOF AP {cdf[cdf.model.eq('Nested LR: expression_only')].iloc[0].average_precision:.4f}; network-only {cdf[cdf.model.eq('Nested LR: network_only')].iloc[0].average_precision:.4f}; combined {cdf[cdf.model.eq('Nested LR: expression_plus_network')].iloc[0].average_precision:.4f}. Combining expression with network did not increase AP over network-only. The nested feature-selection pipeline yielded AP {after['average_precision']:.4f}, ROC-AUC {after['roc_auc']:.4f}, accuracy {after['accuracy']:.4f}, balanced accuracy {after['balanced_accuracy']:.4f}, precision {after['precision']:.4f}, recall {after['recall']:.4f}, F1 {after['f1']:.4f}, and MCC {after['mcc']:.4f}.\n\nA comparable fixed Logistic reference using the same outer folds (C=1, balanced, expression+network) had AP {fixedrow.average_precision:.4f}, ROC-AUC {fixedrow.roc_auc:.4f}, accuracy {fixedrow.accuracy:.4f}, balanced accuracy {fixedrow.balanced_accuracy:.4f}, precision {fixedrow.precision:.4f}, recall {fixedrow.recall:.4f}, F1 {fixedrow.f1:.4f}, and MCC {fixedrow.mcc:.4f}. The tuned inner-selected pipeline changes threshold metrics but does not materially improve ranking AP. This is not evidence of generalization beyond the development cohort. The fixed threshold is retained, and the reported results expose its precision/recall trade-off.\n\nThe Phase 5 sparse Transformer remains the selected candidate by mean fold-seed AP (0.5169) compared with the nested feature-selected Logistic fold AP mean ({float(json.loads((RUN/'metrics/optimization_summary.json').read_text())['nested_selected_fold_ap_mean']):.4f}). This cross-protocol comparison is descriptive: Phase 5 selected epochs on the validation folds, whereas the new Logistic search used nested inner CV. The pooled AP of the old GCN is higher than the selected Transformer, and graph-only Logistic's ordinary accuracy is modestly higher than both, but its recall/F1 are poor. No single model wins all metrics. Therefore there is **no validated before/after performance gain**; the established Transformer checkpoint is preserved as the best current ranking model under the project's declared Phase 5 selection rule.\n\n## Data, imbalance, pseudo-labels, and leakage\n\nThe only training targets remain the frozen NCG `NCG_oncogene` target: 254 positive and 333 explicit-zero labels overall; 469 are in development. Unlabeled genes were never treated as negatives. No additional local gene-label table suitable for training was found. Local reference data include NCBI crosswalk metadata, TCGA sample metadata, STRING aliases, and a restricted COSMIC reference already excluded from training. No data were downloaded and no dependencies installed. IntOGen release 2024.09 provides a public cohort-specific driver catalog, but its driver positives are not validated negatives and its methodology uses COSMIC CGC for calibration; a future use requires release freeze, gene-ID and tissue harmonization, overlap analysis, licensing/provenance review, and an independent evaluation plan before any labels are incorporated ([IntOGen downloads](https://www.intogen.org/download), [IntOGen FAQ](https://www.intogen.org/faq)). COSMIC requires registration/login for noncommercial downloads and a commercial licence for commercial use; local COSMIC content was not redistributed or used to train ([COSMIC downloads and terms](https://cancer.sanger.ac.uk/cosmic/download/cosmic)).\n\nPhase 6's weighted self-training worsened AP slightly and materially worsened Brier/log loss, so pseudo-labeling was not repeated. Weak labels, a small development set, class uncertainty (explicit zero is not biological proof of non-driver), degree-driven visibility, transductive graph features, and selection variation remain limitations. The 80% target cannot be credibly pursued by threshold manipulation.\n\n## Final model and outputs\n\n- Best model before this optimization: **expanded sparse graph Transformer** by Phase 5 mean fold-seed AP; prior Phase 2 NCG-only Logistic had a higher 64.7% accuracy on a different cohort/split, which is not a comparable benchmark.\n- Best model after this optimization: **expanded sparse graph Transformer**, unchanged; no new model credibly displaced it.\n- 80% accuracy: **not achieved**. Highest Phase 5 average fold accuracy was 57.64% for GCN, with zero recall at the pooled 0.5 OOF threshold.\n- Generalization evidence: no clean heldout or independent cohort remains. The previous holdout was exposed; only development CV results are reported for new work.\n- Final checkpoint: `outputs/experiments/{RUN.name}/checkpoints/best_model.pt`\n- Final prediction scores: `outputs/experiments/{RUN.name}/predictions/final_all_gene_predictions.csv`; unknown-only `predictions/final_18411_unknown_predictions.csv`.\n- Model comparison, ablations, inner searches, logs, plots and checks: `{RUN.relative_to(ROOT).as_posix()}/metrics/`, `logs/`, `plots/`.\n- Checkpoint replay maximum score difference from Phase 5 export: {maxdiff:.3g}; integrity checks **{sum(checks.values())}/{len(checks)} passed**.\n\nAll candidate probabilities are model scores, not calibrated probabilities or confirmed biological labels.\n'''
 (ROOT/'reports/final_optimisation_results.md').write_text(report,encoding='utf-8')
 print(json.dumps({'run':str(RUN),'report':'reports/final_optimisation_results.md','max_checkpoint_score_difference':maxdiff,'checks':checks,'best_model':'expanded_sparse_graph_transformer'},indent=2))

if __name__=='__main__':main()
